-- Repairs the Property Management work-order snapshot projection.
-- The repaired aggregate sorts by the emitted createdAt key, so the work-order
-- projection must expose created_at as createdAt. Function-only; no data changes.

BEGIN;

CREATE OR REPLACE FUNCTION public.property_snapshot(p_limit integer DEFAULT 100) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE c uuid:=public.current_company_id(); v_limit integer:=greatest(1,least(coalesce(p_limit,100),200)); v_uid uuid:=auth.uid(); v_restricted boolean:=public.property_has_role(ARRAY['tenant','property_agent','landlord_owner','maintenance_staff']);
BEGIN
  PERFORM public.property_require('view');
  RETURN jsonb_build_object(
    'companyId',c,'currency','TZS','timezone','Africa/Dar_es_Salaam','viewer',jsonb_build_object('id',v_uid,'role',(SELECT role FROM public.profiles WHERE id=v_uid)),
    'permissions',jsonb_build_object('canManage',public.property_can_manage(),'canFinance',public.property_can_finance(),'canApprove',public.property_can_approve(),'canAudit',public.property_can_audit()),
    'metrics',jsonb_build_object(
      'portfolioCount',(SELECT count(*) FROM public.property_portfolios WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid)),
      'propertyCount',(SELECT count(*) FROM public.property_buildings WHERE company_id=c AND (NOT v_restricted OR id IN (SELECT u.building_id FROM public.property_units u JOIN public.property_leases l ON l.unit_id=u.id JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'unitCount',(SELECT count(*) FROM public.property_units WHERE company_id=c AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR id IN (SELECT l.unit_id FROM public.property_leases l JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'occupiedUnits',(SELECT count(*) FROM public.property_units WHERE company_id=c AND status='Occupied' AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR id IN (SELECT l.unit_id FROM public.property_leases l JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),
      'vacantUnits',(SELECT count(*) FROM public.property_units WHERE company_id=c AND status IN ('Available','Reserved') AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid))),
      'occupancyRate',coalesce(round(100.0*(SELECT count(*) FROM public.property_units WHERE company_id=c AND status='Occupied')/nullif((SELECT count(*) FROM public.property_units WHERE company_id=c AND status NOT IN ('Sold','Off Market')),0),2),0),
      'rentalIncome',coalesce((SELECT sum(amount) FROM public.property_payments WHERE company_id=c AND status='Posted' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),0),
      'outstandingRent',coalesce((SELECT sum(total_amount-amount_paid) FROM public.property_invoices WHERE company_id=c AND status IN ('Issued','Partially Paid','Overdue') AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),0),
      'overdueAccounts',(SELECT count(*) FROM public.property_invoices WHERE company_id=c AND status='Overdue' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),
      'maintenanceCosts',coalesce((SELECT sum(actual_cost) FROM public.property_work_orders w WHERE w.company_id=c AND w.status='Completed' AND (NOT v_restricted OR w.request_id IN (SELECT r.id FROM public.property_maintenance_requests r JOIN public.property_leases l ON l.id=r.lease_id JOIN public.property_tenants t ON t.id=l.tenant_id WHERE t.profile_id=v_uid))),0),
      'propertyExpenses',coalesce((SELECT sum(amount) FROM public.property_expenses WHERE company_id=c AND status IN ('Approved','Paid') AND (NOT v_restricted OR created_by=v_uid)),0),
      'upcomingLeaseExpiries',(SELECT count(*) FROM public.property_leases WHERE company_id=c AND status='Active' AND end_date BETWEEN current_date AND current_date+interval '90 days' AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid))),
      'openMaintenance',(SELECT count(*) FROM public.property_maintenance_requests WHERE company_id=c AND status NOT IN ('Closed','Cancelled') AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)))
    ),
    'portfolios',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,portfolio_code AS "portfolioCode",name,description,currency,timezone,status,created_at AS "createdAt" FROM public.property_portfolios WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'owners',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."legalName") FROM (SELECT id,legal_name AS "legalName",owner_type AS "ownerType",phone,email,kyc_status AS "kycStatus",status,created_at AS "createdAt" FROM public.property_owners WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'buildings',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT b.id,b.property_code AS "propertyCode",b.name,b.property_type AS "propertyType",b.address,b.region,b.district,b.ward,b.latitude,b.longitude,b.status,p.name AS "portfolioName" FROM public.property_buildings b JOIN public.property_portfolios p ON p.id=b.portfolio_id WHERE b.company_id=c AND (NOT v_restricted OR b.id IN (SELECT u.building_id FROM public.property_units u JOIN public.property_leases l2 ON l2.unit_id=u.id JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'plots',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."plotCode") FROM (SELECT id,plot_code AS "plotCode",title_number AS "titleNumber",land_use AS "landUse",area_sqm AS "areaSqm",region,district,ward,status FROM public.property_plots WHERE company_id=c AND (NOT v_restricted OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'listings',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT l.id,l.unit_id AS "unitId",l.agent_id AS "agentId",l.listing_type AS "listingType",l.asking_amount AS "askingAmount",l.commission_rate AS "commissionRate",l.status,l.available_from AS "availableFrom",l.expires_at AS "expiresAt",l.description,l.created_at AS "createdAt",u.unit_code AS "unitCode" FROM public.property_listings l JOIN public.property_units u ON u.id=l.unit_id WHERE l.company_id=c AND (NOT v_restricted OR l.agent_id IN (SELECT id FROM public.property_agents WHERE profile_id=v_uid) OR l.unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'units',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."unitCode") FROM (SELECT u.id,u.unit_code AS "unitCode",u.unit_type AS "unitType",u.floor_label AS "floorLabel",u.bedrooms,u.bathrooms,u.area_sqm AS "areaSqm",u.rent_amount AS "rentAmount",u.service_charge_amount AS "serviceChargeAmount",u.deposit_amount AS "depositAmount",u.status,u.building_id AS "buildingId",b.name AS "buildingName" FROM public.property_units u LEFT JOIN public.property_buildings b ON b.id=u.building_id WHERE u.company_id=c AND (NOT v_restricted OR u.owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid) OR u.id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'agents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."fullName") FROM (SELECT id,agent_code AS "agentCode",full_name AS "fullName",phone,email,licence_number AS "licenceNumber",commission_rate AS "commissionRate",status FROM public.property_agents WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'taxRules',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.code) FROM (SELECT id,code,name,applies_to AS "appliesTo",rate,flat_amount AS "flatAmount",status FROM public.property_tax_fee_rules WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'meters',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."utilityType") FROM (SELECT id,unit_id AS "unitId",utility_type AS "utilityType",meter_number AS "meterNumber",unit_of_measure AS "unitOfMeasure",rate,status FROM public.property_utility_meters WHERE company_id=c AND (NOT v_restricted OR unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'serviceCharges',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,unit_id AS "unitId",name,amount,frequency,status,created_at AS "createdAt" FROM public.property_service_charges WHERE company_id=c AND (NOT v_restricted OR unit_id IN (SELECT l2.unit_id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'contractors',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM (SELECT id,contractor_code AS "contractorCode",name,phone,email,trade,tax_number AS "taxNumber",status FROM public.property_contractors WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'tenants',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."fullName") FROM (SELECT id,tenant_code AS "tenantCode",full_name AS "fullName",phone,email,kyc_status AS "kycStatus",status,created_at AS "createdAt" FROM public.property_tenants WHERE company_id=c AND (NOT v_restricted OR profile_id=v_uid OR created_by=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'applications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,application_number AS "applicationNumber",unit_id AS "unitId",tenant_id AS "tenantId",proposed_rent AS "proposedRent",requested_start_date AS "requestedStartDate",status,decision_note AS "decisionNote",created_at AS "createdAt" FROM public.property_applications WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR agent_id IN (SELECT id FROM public.property_agents WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'leases',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."endDate") FROM (SELECT id,lease_number AS "leaseNumber",unit_id AS "unitId",tenant_id AS "tenantId",owner_id AS "ownerId",start_date AS "startDate",end_date AS "endDate",rent_amount AS "rentAmount",service_charge_amount AS "serviceChargeAmount",deposit_amount AS "depositAmount",rent_frequency AS "rentFrequency",status,notice_days AS "noticeDays" FROM public.property_leases WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR owner_id IN (SELECT id FROM public.property_owners WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'invoices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."dueDate" DESC) FROM (SELECT id,invoice_number AS "invoiceNumber",invoice_type AS "invoiceType",lease_id AS "leaseId",tenant_id AS "tenantId",unit_id AS "unitId",period_start AS "periodStart",period_end AS "periodEnd",issue_date AS "issueDate",due_date AS "dueDate",subtotal,tax_amount AS "taxAmount",late_fee_amount AS "lateFeeAmount",total_amount AS "totalAmount",amount_paid AS "amountPaid",status,currency FROM public.property_invoices WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,payment_number AS "paymentNumber",invoice_id AS "invoiceId",tenant_id AS "tenantId",amount,payment_method AS "paymentMethod",provider_code AS "providerCode",provider_reference AS "providerReference",status,paid_at AS "paidAt",created_at AS "createdAt" FROM public.property_payments WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'receipts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."issuedAt" DESC) FROM (SELECT r.id,r.payment_id AS "paymentId",r.receipt_number AS "receiptNumber",r.channel,r.recipient_phone AS "recipientPhone",r.issued_at AS "issuedAt" FROM public.property_receipts r JOIN public.property_payments p ON p.id=r.payment_id WHERE r.company_id=c AND (NOT v_restricted OR p.tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'maintenanceRequests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."requestedAt" DESC) FROM (SELECT id,request_number AS "requestNumber",unit_id AS "unitId",tenant_id AS "tenantId",category,priority,title,description,status,requested_at AS "requestedAt",completed_at AS "completedAt" FROM public.property_maintenance_requests WHERE company_id=c AND (NOT v_restricted OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR created_by=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'inspections',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."inspectionDate" DESC) FROM (SELECT id,lease_id AS "leaseId",inspection_type AS "inspectionType",inspection_date AS "inspectionDate",condition_summary AS "conditionSummary",status,inspector_id AS "inspectorId",created_at AS "createdAt" FROM public.property_inspections WHERE company_id=c AND (NOT v_restricted OR lease_id IN (SELECT l2.id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'handovers',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."handoverDate" DESC) FROM (SELECT id,lease_id AS "leaseId",handover_type AS "handoverType",handover_date AS "handoverDate",keys_count AS "keysCount",signed_by_tenant AS "signedByTenant",signed_by_manager AS "signedByManager",notes,created_at AS "createdAt" FROM public.property_handover_records WHERE company_id=c AND (NOT v_restricted OR lease_id IN (SELECT l2.id FROM public.property_leases l2 JOIN public.property_tenants t2 ON t2.id=l2.tenant_id WHERE t2.profile_id=v_uid)) LIMIT v_limit)x),'[]'::jsonb),
    'workOrders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,work_order_number AS "workOrderNumber",request_id AS "requestId",contractor_id AS "contractorId",assigned_profile_id AS "assignedProfileId",estimated_cost AS "estimatedCost",actual_cost AS "actualCost",status,due_date AS "dueDate",completion_note AS "completionNote",created_at AS "createdAt" FROM public.property_work_orders WHERE company_id=c AND (NOT v_restricted OR assigned_profile_id=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'expenses',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."expenseDate" DESC) FROM (SELECT id,expense_number AS "expenseNumber",property_id AS "propertyId",unit_id AS "unitId",category,description,amount,expense_date AS "expenseDate",status,payment_method AS "paymentMethod" FROM public.property_expenses WHERE company_id=c AND (NOT v_restricted OR created_by=v_uid) LIMIT v_limit)x),'[]'::jsonb),
    'budgets',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."fiscalYear" DESC,x.category) FROM (SELECT id,portfolio_id AS "portfolioId",fiscal_year AS "fiscalYear",category,budget_amount AS "budgetAmount",status,approved_by AS "approvedBy",approved_at AS "approvedAt",created_at AS "createdAt" FROM public.property_budgets WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'insurances',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."endDate") FROM (SELECT id,property_id AS "propertyId",unit_id AS "unitId",insurer,policy_number AS "policyNumber",cover_type AS "coverType",premium,start_date AS "startDate",end_date AS "endDate",status,notes FROM public.property_insurances WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'reconciliations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,payment_id AS "paymentId",invoice_id AS "invoiceId",expected_amount AS "expectedAmount",actual_amount AS "actualAmount",variance,status,notes,created_at AS "createdAt" FROM public.property_reconciliations WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'approvals',CASE WHEN public.property_can_approve() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."requestedAt" DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",action,status,requested_by AS "requestedBy",decided_by AS "decidedBy",note,requested_at AS "requestedAt",decided_at AS "decidedAt" FROM public.property_approvals WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb) ELSE '[]'::jsonb END,
    'integrationEvents',CASE WHEN public.property_can_audit() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,target_module AS "targetModule",entity_type AS "entityType",entity_id AS "entityId",event_type AS "eventType",status,created_at AS "createdAt" FROM public.property_integration_events WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb) ELSE '[]'::jsonb END,
    'documents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",document_type AS "documentType",title,storage_key AS "storageKey",file_url AS "fileUrl",document_date AS "documentDate",expires_at AS "expiresAt",verification_status AS "verificationStatus",created_at AS "createdAt" FROM public.property_documents WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb),
    'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,notification_type AS "notificationType",title,body,channel,status,scheduled_for AS "scheduledFor",created_at AS "createdAt" FROM public.property_notifications WHERE company_id=c AND (recipient_profile_id=v_uid OR tenant_id IN (SELECT id FROM public.property_tenants WHERE profile_id=v_uid) OR NOT v_restricted) LIMIT v_limit)x),'[]'::jsonb),
    'audit',CASE WHEN public.property_can_audit() THEN coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,actor_id AS "actorId",action,entity_type AS "entityType",entity_id AS "entityId",details,created_at AS "createdAt" FROM public.property_audit_log WHERE company_id=c LIMIT v_limit)x),'[]'::jsonb) ELSE '[]'::jsonb END
  );
END; $$;

CREATE OR REPLACE FUNCTION public.property_tenant_snapshot(p_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE c uuid:=public.current_company_id(); v_limit integer:=greatest(1,least(coalesce(p_limit,50),100)); v_tenant public.property_tenants%ROWTYPE;
BEGIN
  SELECT * INTO v_tenant FROM public.property_tenants WHERE company_id=c AND profile_id=auth.uid() AND status='Active' LIMIT 1;
  IF v_tenant.id IS NULL THEN RAISE EXCEPTION 'No active Property Management tenant profile is linked to this account.' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'tenant',jsonb_build_object('id',v_tenant.id,'tenantCode',v_tenant.tenant_code,'fullName',v_tenant.full_name,'phone',v_tenant.phone,'email',v_tenant.email,'kycStatus',v_tenant.kyc_status,'status',v_tenant.status),
    'currency','TZS','timezone','Africa/Dar_es_Salaam',
    'leases',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."endDate") FROM (SELECT id,lease_number AS "leaseNumber",unit_id AS "unitId",start_date AS "startDate",end_date AS "endDate",rent_amount AS "rentAmount",service_charge_amount AS "serviceChargeAmount",deposit_amount AS "depositAmount",rent_frequency AS "rentFrequency",status,notice_days AS "noticeDays" FROM public.property_leases WHERE company_id=c AND tenant_id=v_tenant.id LIMIT v_limit)x),'[]'::jsonb),
    'invoices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."dueDate" DESC) FROM (SELECT id,invoice_number AS "invoiceNumber",invoice_type AS "invoiceType",lease_id AS "leaseId",unit_id AS "unitId",period_start AS "periodStart",period_end AS "periodEnd",due_date AS "dueDate",total_amount AS "totalAmount",amount_paid AS "amountPaid",status,currency FROM public.property_invoices WHERE company_id=c AND tenant_id=v_tenant.id LIMIT v_limit)x),'[]'::jsonb),
    'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,payment_number AS "paymentNumber",invoice_id AS "invoiceId",amount,payment_method AS "paymentMethod",provider_reference AS "providerReference",status,paid_at AS "paidAt",created_at AS "createdAt" FROM public.property_payments WHERE company_id=c AND tenant_id=v_tenant.id LIMIT v_limit)x),'[]'::jsonb),
    'maintenanceRequests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."requestedAt" DESC) FROM (SELECT id,request_number AS "requestNumber",unit_id AS "unitId",category,priority,title,description,status,requested_at AS "requestedAt",completed_at AS "completedAt" FROM public.property_maintenance_requests WHERE company_id=c AND tenant_id=v_tenant.id LIMIT v_limit)x),'[]'::jsonb),
    'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,notification_type AS "notificationType",title,body,channel,status,created_at AS "createdAt" FROM public.property_notifications WHERE company_id=c AND (tenant_id=v_tenant.id OR recipient_profile_id=auth.uid()) LIMIT v_limit)x),'[]'::jsonb),
    'documents',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."createdAt" DESC) FROM (SELECT id,entity_type AS "entityType",entity_id AS "entityId",document_type AS "documentType",title,file_url AS "fileUrl",expires_at AS "expiresAt",verification_status AS "verificationStatus",created_at AS "createdAt" FROM public.property_documents WHERE company_id=c AND ((entity_type='Tenant' AND entity_id=v_tenant.id) OR (entity_type='Lease' AND entity_id IN (SELECT id FROM public.property_leases WHERE company_id=c AND tenant_id=v_tenant.id))) LIMIT v_limit)x),'[]'::jsonb)
  );
END; $$;

REVOKE ALL ON FUNCTION public.property_snapshot(integer) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.property_tenant_snapshot(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.property_snapshot(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.property_tenant_snapshot(integer) TO authenticated;

COMMIT;
